const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'Ultra Sound Money';
pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium";

// Color palette
const BG = "0B0E1A";
const CARD_BG = "1C2038";
const ETH_BLUE = "627EEA";
const CYAN = "00D4FF";
const GREEN = "00FFA3";
const RED = "FF6B6B";
const GOLD = "FFB800";
const WHITE = "F0F4FF";
const MUTED = "7B85A0";
const GRID_LINE = "2A2F4A";

// Fresh shadow factory (must create new object each call)
const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.25 });

// ====== SLIDE 1: Title ======
let slide1 = pres.addSlide();
slide1.background = { color: BG };

slide1.addText("Ultra Sound Money", {
  x: 0.8, y: 1.0, w: 8.4, h: 1.2,
  fontSize: 44, fontFace: "Georgia", color: WHITE, bold: true, align: "left", margin: 0
});

slide1.addText("Ethereum's Post-Merge Supply Dynamics\nand Monetary Premium", {
  x: 0.8, y: 2.3, w: 8.4, h: 0.9,
  fontSize: 20, fontFace: "Calibri", color: CYAN, align: "left", margin: 0
});

slide1.addText([
  { text: "Current Supply ", options: { color: MUTED, fontSize: 13 } },
  { text: "121.6M ETH", options: { color: WHITE, fontSize: 13, bold: true } },
  { text: "   |   ", options: { color: MUTED, fontSize: 13 } },
  { text: "Gas ", options: { color: MUTED, fontSize: 13 } },
  { text: "0.1 Gwei", options: { color: WHITE, fontSize: 13, bold: true } },
  { text: "   |   ", options: { color: MUTED, fontSize: 13 } },
  { text: "ETH Price ", options: { color: MUTED, fontSize: 13 } },
  { text: "$2,243", options: { color: WHITE, fontSize: 13, bold: true } },
], {
  x: 0.8, y: 3.5, w: 8.4, h: 0.4,
  fontFace: "Calibri", align: "left", margin: 0
});

// Decorative diamond shapes (Ethereum-inspired motif)
slide1.addShape(pres.shapes.DIAMOND, {
  x: 8.5, y: 0.5, w: 1.0, h: 1.0,
  fill: { color: ETH_BLUE, transparency: 30 },
  line: { color: ETH_BLUE, width: 1.5 }
});
slide1.addShape(pres.shapes.DIAMOND, {
  x: 8.9, y: 1.2, w: 0.5, h: 0.5,
  fill: { color: CYAN, transparency: 50 },
  line: { color: CYAN, width: 1 }
});

slide1.addText("Source: ultrasound.money", {
  x: 0.8, y: 4.9, w: 4, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: MUTED, align: "left", margin: 0
});

// ====== SLIDE 2: Supply Change Snapshot ======
let slide2 = pres.addSlide();
slide2.background = { color: BG };

slide2.addText("ETH Supply Growing at +0.83%/Year", {
  x: 0.5, y: 0.3, w: 9, h: 0.5,
  fontSize: 26, fontFace: "Georgia", color: WHITE, bold: true, align: "left", margin: 0
});

slide2.addText("Only 192 ETH Burned in 7 Days — 0.01x Issuance Offset Ratio", {
  x: 0.5, y: 0.85, w: 9, h: 0.35,
  fontSize: 14, fontFace: "Calibri", color: MUTED, align: "left", margin: 0
});

// Bar chart: Issuance vs Burn
slide2.addChart(pres.charts.BAR, [
  {
    name: "ETH",
    labels: ["Issuance (7-day)", "Burn (7-day)"],
    values: [19638, 192]
  }
], {
  x: 0.5, y: 1.4, w: 5.5, h: 3.5,
  barDir: "col",
  chartColors: [RED, GREEN],
  chartArea: { fill: { color: CARD_BG } },
  catAxisLabelColor: MUTED,
  catAxisLabelFontSize: 10,
  valAxisLabelColor: MUTED,
  valGridLine: { color: GRID_LINE, size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: WHITE,
  showLegend: false,
  showTitle: false
});

// Key stats cards on right
// Card: Current Supply
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 6.5, y: 1.4, w: 3, h: 0.85,
  fill: { color: CARD_BG }, shadow: makeShadow()
});
slide2.addText("Current Supply", {
  x: 6.7, y: 1.45, w: 2.6, h: 0.3,
  fontSize: 11, fontFace: "Calibri", color: MUTED, margin: 0
});
slide2.addText("121,603,980 ETH", {
  x: 6.7, y: 1.75, w: 2.6, h: 0.4,
  fontSize: 16, fontFace: "Georgia", color: WHITE, bold: true, margin: 0
