  x: 6.5, y: 4.6, w: 3, h: 0.35,
  fontSize: 12, fontFace: "Calibri", color: GOLD, italic: true, align: "center", margin: 0
});

// ====== SLIDE 3: Gas and Burn Mechanics ======
let slide3 = pres.addSlide();
slide3.background = { color: BG };

slide3.addText("Base Gas at Historic Lows", {
  x: 0.5, y: 0.3, w: 9, h: 0.5,
  fontSize: 26, fontFace: "Georgia", color: WHITE, bold: true, align: "left", margin: 0
