], {
  x: 0.7, y: 1.5, w: 4.1, h: 0.9,
  fontFace: "Calibri", margin: 0
});

// Gas range gauge card
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 2.8, w: 9, h: 1.5,
  fill: { color: CARD_BG }, shadow: makeShadow()
});

slide3.addText("7-Day Gas Market Range", {
  x: 0.8, y: 2.9, w: 4, h: 0.3,
  fontSize: 13, fontFace: "Georgia", color: WHITE, bold: true, margin: 0
});

slide3.addText([
  { text: "Min: ", options: { color: MUTED, fontSize: 11 } },
  { text: "0.0 Gwei", options: { color: WHITE, fontSize: 11, bold: true } },
  { text: "    Avg: ", options: { color: MUTED, fontSize: 11 } },
  { text: "0.1 Gwei", options: { color: GREEN, fontSize: 11, bold: true } },
  { text: "    Max: ", options: { color: MUTED, fontSize: 11 } },
  { text: "1.3 Gwei", options: { color: WHITE, fontSize: 11, bold: true } },
], {
  x: 4.5, y: 2.9, w: 4.7, h: 0.3,
  fontFace: "Calibri", margin: 0
});

// Gauge bar background (full range)
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.8, y: 3.5, w: 8.0, h: 0.25,
  fill: { color: GRID_LINE }
});
// Current average position (0.1/1.3 * 8.0)
const avgGaugeW = Math.max((0.1 / 1.3) * 8.0, 0.15);
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.8, y: 3.5, w: avgGaugeW, h: 0.25,
  fill: { color: GREEN }
});

// 22 Gwei equilibrium marker (way off scale - show as arrow/label at right)
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 8.75, y: 3.3, w: 0.05, h: 0.65,
  fill: { color: RED }
