  { text: "1.2%/yr", options: { color: WHITE, fontSize: 10, bold: true, breakLine: true } },
  { text: "", options: { fontSize: 4, breakLine: true } },
  { text: "Equilibrium: ", options: { color: MUTED, fontSize: 10 } },
  { text: "125.7M ETH", options: { color: GOLD, fontSize: 10, bold: true } },
], {
  x: 7.45, y: 1.8, w: 1.9, h: 3.0,
  fontFace: "Calibri", margin: 0
});

// Era history note
slide6.addText("Era transitions: Genesis (5 ETH/block) → Byzantium (3) → Constantinople (2) → Phase 0 staking → London burn → Merge (PoW removal)", {
  x: 0.5, y: 5.15, w: 9, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: MUTED, align: "center", margin: 0
});

// ====== SLIDE 7: Flippening and TVS ======
let slide7 = pres.addSlide();
slide7.background = { color: BG };

slide7.addText("ETH at 18.7% of Bitcoin's Market Cap", {
  x: 0.5, y: 0.3, w: 9, h: 0.5,
  fontSize: 26, fontFace: "Georgia", color: WHITE, bold: true, align: "left", margin: 0
});

slide7.addText("Securing $272B in Native Value  |  $307B+ Total Value Secured", {
  x: 0.5, y: 0.85, w: 9, h: 0.35,
  fontSize: 14, fontFace: "Calibri", color: MUTED, align: "left", margin: 0
});

// Pie chart for TVS composition
slide7.addChart(pres.charts.PIE, [
  {
    name: "Total Value Secured",
    labels: ["ETH (Native) $272.76B", "ERC20 Tokens $22.21B", "NFTs $12.66B"],
    values: [272.76, 22.21, 12.66]
  }
], {
  x: 0.3, y: 1.3, w: 4.5, h: 3.5,
  chartColors: [ETH_BLUE, CYAN, GOLD],
  showPercent: true,
  showTitle: false,
  showLegend: true,
  legendPos: "b",
  legendColor: MUTED,
  legendFontSize: 9,
  dataLabelColor: WHITE,
  chartArea: { fill: { color: CARD_BG } }
});

// Right panel: Flippening + Top assets
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 5.0, y: 1.3, w: 4.5, h: 1.7,
  fill: { color: CARD_BG }, shadow: makeShadow()
});

slide7.addText("Flippening Progress", {
  x: 5.2, y: 1.4, w: 4.1, h: 0.3,
  fontSize: 13, fontFace: "Georgia", color: CYAN, bold: true, margin: 0
});

// Flippening bars - visual representation
slide7.addText([
  { text: "Bitcoin", options: { color: MUTED, fontSize: 11, breakLine: true } },
  { text: "18.70%", options: { color: GOLD, fontSize: 18, bold: true, breakLine: true } },
], {
  x: 5.2, y: 1.75, w: 1.3, h: 0.6,
  fontFace: "Calibri", margin: 0
});
slide7.addText([
  { text: "USD", options: { color: MUTED, fontSize: 11, breakLine: true } },
  { text: "1.30%", options: { color: WHITE, fontSize: 18, bold: true, breakLine: true } },
], {
  x: 6.6, y: 1.75, w: 1.3, h: 0.6,
  fontFace: "Calibri", margin: 0
});
slide7.addText([
  { text: "Gold", options: { color: MUTED, fontSize: 11, breakLine: true } },
  { text: "0.89%", options: { color: WHITE, fontSize: 18, bold: true, breakLine: true } },
], {
  x: 8.0, y: 1.75, w: 1.3, h: 0.6,
  fontFace: "Calibri", margin: 0
});

// Top ERC20s card
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 5.0, y: 3.2, w: 2.15, h: 1.9,
  fill: { color: CARD_BG }, shadow: makeShadow()
});

slide7.addText("Top ERC20s", {
  x: 5.15, y: 3.25, w: 1.85, h: 0.25,
  fontSize: 11, fontFace: "Georgia", color: CYAN, bold: true, margin: 0
});

slide7.addText([
  { text: "Dai ", options: { color: WHITE, fontSize: 10 } },
  { text: "$4.41B", options: { color: GREEN, fontSize: 10, breakLine: true } },
  { text: "Shiba Inu ", options: { color: WHITE, fontSize: 10 } },
  { text: "$3.51B", options: { color: GREEN, fontSize: 10, breakLine: true } },
  { text: "Cronos ", options: { color: WHITE, fontSize: 10 } },
  { text: "$2.97B", options: { color: GREEN, fontSize: 10, breakLine: true } },
  { text: "Tether Gold ", options: { color: WHITE, fontSize: 10 } },
  { text: "$2.65B", options: { color: GREEN, fontSize: 10 } },
], {
  x: 5.15, y: 3.55, w: 1.85, h: 1.4,
  fontFace: "Calibri", margin: 0
});

// Top NFTs card
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 7.35, y: 3.2, w: 2.15, h: 1.9,
  fill: { color: CARD_BG }, shadow: makeShadow()
});

slide7.addText("Top NFTs", {
  x: 7.5, y: 3.25, w: 1.85, h: 0.25,
  fontSize: 11, fontFace: "Georgia", color: CYAN, bold: true, margin: 0
});

slide7.addText([
  { text: "CryptoPunks ", options: { color: WHITE, fontSize: 10 } },
  { text: "$2.13B", options: { color: GREEN, fontSize: 10, breakLine: true } },
  { text: "BAYC ", options: { color: WHITE, fontSize: 10 } },
  { text: "$0.68B", options: { color: GREEN, fontSize: 10, breakLine: true } },
  { text: "ENS ", options: { color: WHITE, fontSize: 10 } },
  { text: "$0.63B", options: { color: GREEN, fontSize: 10, breakLine: true } },
  { text: "Pudgy Penguins ", options: { color: WHITE, fontSize: 10 } },
  { text: "$0.51B", options: { color: GREEN, fontSize: 10 } },
], {
  x: 7.5, y: 3.55, w: 1.85, h: 1.4,
  fontFace: "Calibri", margin: 0
});

// ====== SLIDE 8: Key Takeaways ======
let slide8 = pres.addSlide();
slide8.background = { color: BG };

slide8.addText("Key Takeaways", {
  x: 0.5, y: 0.3, w: 9, h: 0.5,
  fontSize: 30, fontFace: "Georgia", color: WHITE, bold: true, align: "left", margin: 0
});

slide8.addText("Ultra Sound Money Thesis Intact — Gas Activity Is the Critical Variable", {
  x: 0.5, y: 0.85, w: 9, h: 0.35,
  fontSize: 14, fontFace: "Calibri", color: CYAN, italic: true, align: "left", margin: 0
});

const takeaways = [
  { num: "01", title: "Currently Inflationary", desc: "ETH is slightly inflationary at +0.83%/yr due to historically low gas fees (avg 0.1 Gwei), with burns offsetting only ~1% of issuance.", accent: RED },
  { num: "02", title: "Burn Requires Activity", desc: "The burn mechanism works but requires sustained on-chain activity. DeFi and ETH transfers drive 85% of burn volume.", accent: GOLD },
  { num: "03", title: "Staking Locks Supply", desc: "38.9M ETH (32% of supply) is staked, creating significant supply lock with 9.1M ETH locked for avg 10.7 years.", accent: GREEN },
  { num: "04", title: "Structural Equilibrium Sound", desc: "Long-term equilibrium at 125.7M ETH is structurally sound, requiring sustained ~22 Gwei average gas to balance issuance and burn.", accent: ETH_BLUE },
  { num: "05", title: "Growing Monetary Premium", desc: "18.7% of Bitcoin's market cap and $307B+ TVS demonstrate growing but still early monetary premium.", accent: CYAN }
];

takeaways.forEach((t, i) => {
  const yPos = 1.4 + i * 0.78;

  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: yPos, w: 9, h: 0.68,
    fill: { color: CARD_BG }, shadow: makeShadow()
  });

  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: yPos, w: 0.06, h: 0.68,
    fill: { color: t.accent }
  });

  slide8.addText(t.num, {
    x: 0.7, y: yPos, w: 0.5, h: 0.68,
    fontSize: 22, fontFace: "Georgia", color: t.accent, bold: true, valign: "middle", margin: 0
  });

  slide8.addText([
    { text: t.title, options: { bold: true, color: WHITE, fontSize: 13, breakLine: true } },
    { text: t.desc, options: { color: MUTED, fontSize: 11 } }
  ], {
    x: 1.3, y: yPos, w: 8, h: 0.68,
    fontFace: "Calibri", valign: "middle", margin: 0
  });
});

// Forward-looking statement
slide8.addText([
  { text: "The ultra sound money thesis depends on on-chain activity recovery.", options: { color: WHITE, fontSize: 12, italic: true, bold: true, breakLine: true } },
  { text: "At current gas levels, ETH remains inflationary — but the structural mechanism for deflation is built and waiting.", options: { color: MUTED, fontSize: 11 } }
], {
  x: 0.5, y: 5.0, w: 9, h: 0.5,
  fontFace: "Calibri", align: "center", margin: 0
});

// Write file
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("SUCCESS: Presentation saved to /app/output/final_deck.pptx"))
  .catch(err => console.error("ERROR:", err));

